solution_code:
def parsear_edad(texto):
    try:
        edad = int(str(texto).strip())
    except (TypeError, ValueError) as exc:
        raise ValueError("La edad debe ser un numero entero") from exc
    if not 0 <= edad <= 120:
        raise ValueError("La edad debe estar entre 0 y 120")
    return edad

