import pytest

from exercise_student import parsear_edad


def test_parsea_una_edad_valida():
    assert parsear_edad(" 25 ") == 25


def test_rechaza_un_texto_no_numerico():
    with pytest.raises(ValueError):
        parsear_edad("abc")


def test_rechaza_una_edad_fuera_de_rango():
    with pytest.raises(ValueError):
        parsear_edad("150")
